import fs from 'node:fs';
import path from 'node:path';

const DIST_DIR = path.resolve(process.cwd(), 'dist');

const SPA_ROUTES = [
  'studio',
  'studio/designer',
  'studio/parts',
  'studio/cutlist',
  'studio/optimizer',
  'studio/budget',
  'studio/labels',
  'auth',
  'admin',
  'terms',
  'privacy',
  'refunds',
];

/**
 * Recursively searches `dist/` using breadth-first traversal to locate the
 * root `index.html` generated by Angular (`dist/<project>/browser/index.html`
 * or `dist/<project>/index.html`).
 */
function findAngularOutputDir(rootDir) {
  if (!fs.existsSync(rootDir)) {
    throw new Error(`Build output directory not found: ${rootDir}`);
  }

  let currentLevel = [rootDir];

  while (currentLevel.length > 0) {
    const htmlMatches = [];
    const nextLevel = [];

    for (const dir of currentLevel) {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      const hasIndexHtml = entries.some(
        (entry) => entry.isFile() && entry.name === 'index.html'
      );

      if (hasIndexHtml) {
        htmlMatches.push(dir);
      }

      for (const entry of entries) {
        if (entry.isDirectory() && entry.name !== 'server') {
          nextLevel.push(path.join(dir, entry.name));
        }
      }
    }

    if (htmlMatches.length > 0) {
      const browserMatch = htmlMatches.find(
        (dir) => path.basename(dir) === 'browser'
      );
      return browserMatch ?? htmlMatches[0];
    }

    currentLevel = nextLevel;
  }

  throw new Error(
    `Could not locate index.html inside ${rootDir}. Ensure Angular built in SPA mode.`
  );
}

function generatePhysicalSpaRoutes() {
  const outputDir = findAngularOutputDir(DIST_DIR);
  const sourceIndexPath = path.join(outputDir, 'index.html');
  const generatedFiles = [];

  for (const fallbackName of ['404.html', '200.html']) {
    const targetPath = path.join(outputDir, fallbackName);
    fs.copyFileSync(sourceIndexPath, targetPath);
    generatedFiles.push(targetPath);
  }

  for (const route of SPA_ROUTES) {
    const routeDir = path.join(outputDir, route);
    fs.mkdirSync(routeDir, { recursive: true });
    const targetPath = path.join(routeDir, 'index.html');
    fs.copyFileSync(sourceIndexPath, targetPath);
    generatedFiles.push(targetPath);
  }

  const relativeOutputDir = path.relative(process.cwd(), outputDir).replaceAll('\\', '/');
  console.log(`[postbuild-spa] Detected Angular output directory: ${relativeOutputDir}`);
  console.log(`[postbuild-spa] Generated ${generatedFiles.length} physical SPA route files:`);

  for (const filePath of generatedFiles) {
    const relativeFile = path.relative(process.cwd(), filePath).replaceAll('\\', '/');
    console.log(`  - ${relativeFile}`);
  }
}

generatePhysicalSpaRoutes();
